import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.BTjPRYTP.js";const p=JSON.parse('{"title":"TeslaSync v0.25.0 Upgrade Notes","description":"","frontmatter":{},"headers":[],"relativePath":"upgrade-notes-v0.25.md","filePath":"upgrade-notes-v0.25.md"}'),n={name:"upgrade-notes-v0.25.md"};function o(l,e,s,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="teslasync-v0-25-0-upgrade-notes" tabindex="-1">TeslaSync v0.25.0 Upgrade Notes <a class="header-anchor" href="#teslasync-v0-25-0-upgrade-notes" aria-label="Permalink to &quot;TeslaSync v0.25.0 Upgrade Notes&quot;">​</a></h1><h2 id="what-s-new" tabindex="-1">What&#39;s New <a class="header-anchor" href="#what-s-new" aria-label="Permalink to &quot;What&#39;s New&quot;">​</a></h2><h3 id="comprehensive-drive-session-tracking" tabindex="-1">Comprehensive Drive Session Tracking <a class="header-anchor" href="#comprehensive-drive-session-tracking" aria-label="Permalink to &quot;Comprehensive Drive Session Tracking&quot;">​</a></h3><ul><li>All telemetry data (speed, power, temperature, tire pressure, SOC, elevation) is now tracked continuously throughout drives</li><li>Drive distance computed from odometer readings (no longer shows 0)</li><li>Start/end addresses automatically resolved via OpenStreetMap Nominatim</li><li>Full drive statistics: speed mean/max/min, range stats, SOC stats, elevation gain/loss</li></ul><h3 id="enhanced-charging-sessions" tabindex="-1">Enhanced Charging Sessions <a class="header-anchor" href="#enhanced-charging-sessions" aria-label="Permalink to &quot;Enhanced Charging Sessions&quot;">​</a></h3><ul><li>Continuous power, voltage, temperature, and SOC tracking during charges</li><li>Automatic cost calculation based on geofence electricity rates</li><li>Energy estimation from battery % diff when direct signals unavailable</li><li>Location tracking and reverse geocoding for charge locations</li></ul><h3 id="telemetry-pipeline-improvements" tabindex="-1">Telemetry Pipeline Improvements <a class="header-anchor" href="#telemetry-pipeline-improvements" aria-label="Permalink to &quot;Telemetry Pipeline Improvements&quot;">​</a></h3><ul><li>Graceful shutdown: all background goroutines properly cancelled on SIGTERM</li><li>toFloat ok-pattern: correctly handles actual 0% battery level (no more false negatives)</li><li>Stale session cleanup: drives/charges left open due to disconnects are auto-closed</li><li>Fleet telemetry subscription persistence for audit trail</li></ul><h3 id="ui-enhancements" tabindex="-1">UI Enhancements <a class="header-anchor" href="#ui-enhancements" aria-label="Permalink to &quot;UI Enhancements&quot;">​</a></h3><ul><li>Redesigned tire pressure visualization (realistic Model Y SVG)</li><li>Enhanced analytics page (speed distribution, efficiency trends, charging costs)</li><li>Mileage over time graph</li><li>Charging curve with real telemetry data</li><li>Elevation profile with speed overlay</li><li>All unit strings now respect user preferences (no more hardcoded km/mi)</li></ul><h3 id="security-performance" tabindex="-1">Security &amp; Performance <a class="header-anchor" href="#security-performance" aria-label="Permalink to &quot;Security &amp; Performance&quot;">​</a></h3><ul><li>Rate limits on all sensitive endpoints</li><li>N+1 queries consolidated</li><li>LIMIT guards on all GetAll queries</li><li>Geofence spatial index</li></ul><h2 id="database-migration" tabindex="-1">Database Migration <a class="header-anchor" href="#database-migration" aria-label="Permalink to &quot;Database Migration&quot;">​</a></h2><p>Migration 21 adds new columns and tables. The migration runs automatically on startup.</p><p>No manual intervention required — existing data is preserved, new columns are nullable.</p><h3 id="new-tables" tabindex="-1">New Tables <a class="header-anchor" href="#new-tables" aria-label="Permalink to &quot;New Tables&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Table</th><th>Purpose</th></tr></thead><tbody><tr><td><code>drive_telemetry_readings</code></td><td>Continuous drive telemetry (position, speed, power, battery, temps, tires)</td></tr><tr><td><code>charge_telemetry_readings</code></td><td>Continuous charge telemetry (power, voltage, SOC, temps, location)</td></tr><tr><td><code>fleet_telemetry_subscriptions</code></td><td>Subscription audit trail</td></tr></tbody></table><h3 id="new-indexes" tabindex="-1">New Indexes <a class="header-anchor" href="#new-indexes" aria-label="Permalink to &quot;New Indexes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Index</th><th>Purpose</th></tr></thead><tbody><tr><td><code>idx_geofences_coords</code></td><td>Spatial lookup optimization</td></tr></tbody></table><h2 id="new-api-endpoints" tabindex="-1">New API Endpoints <a class="header-anchor" href="#new-api-endpoints" aria-label="Permalink to &quot;New API Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Description</th></tr></thead><tbody><tr><td><code>GET /api/v1/drives/{driveID}/telemetry</code></td><td>Continuous telemetry readings for a drive</td></tr><tr><td><code>GET /api/v1/charging/{sessionID}/telemetry</code></td><td>Continuous telemetry readings for a charge session</td></tr></tbody></table><p>See <a href="./api-reference.html">API Reference</a> for full details.</p><h2 id="breaking-changes" tabindex="-1">Breaking Changes <a class="header-anchor" href="#breaking-changes" aria-label="Permalink to &quot;Breaking Changes&quot;">​</a></h2><p>None. All changes are additive.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>No new environment variables or configuration changes required. All features are enabled by default.</p><h3 id="optional-nominatim" tabindex="-1">Optional: Nominatim <a class="header-anchor" href="#optional-nominatim" aria-label="Permalink to &quot;Optional: Nominatim&quot;">​</a></h3><p>Address resolution uses the public OpenStreetMap Nominatim API by default. For high-volume deployments, consider self-hosting Nominatim to avoid rate limits. Set <code>NOMINATIM_URL</code> environment variable to point to your instance.</p><h2 id="upgrade-steps" tabindex="-1">Upgrade Steps <a class="header-anchor" href="#upgrade-steps" aria-label="Permalink to &quot;Upgrade Steps&quot;">​</a></h2><ol><li>Pull the latest image or build from source</li><li>Start the application — migration 21 runs automatically</li><li>New drives and charges will immediately benefit from enhanced tracking</li><li>Existing historical data is preserved; new fields will populate on future sessions</li></ol>',30)])])}const m=a(n,[["render",o]]);export{p as __pageData,m as default};
